#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$REPO_ROOT/.env"
AWS_DIR="${HOME}/.aws"
CRED_FILE="$AWS_DIR/credentials"
PY="uv run python"

# ask_number KEY "Prompt" — like ask, but rejects anything that is not a number.
ask_number() {
  local key="$1" prompt="$2" input
  while true; do
    ask "$key" "$prompt"
    local value; value="${!key}"
    if [[ "$value" =~ ^[0-9]+([.][0-9]+)?$ ]]; then return 0; fi
    warn "that is not a number — enter digits only, e.g. 1.00 or 15"
  done
}

# write_aws_credentials writes ~/.aws/credentials with 0600 permissions.
# Credentials deliberately do NOT go into the repository's .env: the repo is public and
# .env sits inside it, one careless `git add -A` from exposure.
write_aws_credentials() {
  mkdir -p "$AWS_DIR"
  chmod 700 "$AWS_DIR"
  umask 077
  {
    printf '[default]\n'
    printf 'aws_access_key_id = %s\n' "$AWS_ACCESS_KEY_ID"
    printf 'aws_secret_access_key = %s\n' "$AWS_SECRET_ACCESS_KEY"
    printf 'region = eu-north-1\n'
  } > "$CRED_FILE"
  chmod 600 "$CRED_FILE"
  WRITTEN_SECRET+=("~/.aws/credentials")
  printf '  %s✓ wrote%s %s (mode 0600)\n' "$GREEN" "$RESET" "$CRED_FILE"
}

banner "Phase 0 · AWS account, guardrails and Bedrock access"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Create the AWS account"
say "Only you can do this: it needs your email, your card and phone verification."
note "Budget 10–15 minutes. Nothing here is charged; Bedrock bills per token, and the"
note "alarm in stage 5 caps the damage at 10 USD/month."
open_url "https://portal.aws.amazon.com/billing/signup"
step "Use an email address NOT already tied to an AWS account, and a password manager entry."
warn "Prefer the PAID plan (Pay-as-you-go)."
note "A Free-plan account hits 'ThrottlingException: Too many tokens per day' on every"
note "Bedrock model, including Amazon's own, while its listed quotas sit unused in the"
note "hundreds of millions. Credits are not the constraint — the plan is. See docs/PHASE0.md."
step "Choose 'Personal' account type and the paid plan. A card is required either way."
step "Enter the payment card."
step "Complete the phone verification."
step "If AWS asks for identity verification, do it now — model access waits on it."
warn "Never create an access key for the ROOT user. Stage 3 creates a scoped IAM user."
pause "Press Enter once you can see the AWS Console home page."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Secure the root user"
say "The root user is the one account that can never be restricted. Lock it down, then"
say "stop using it. You will not log in as root again for this project."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "Under 'Multi-factor authentication (MFA)', click 'Assign MFA device'."
step "Name it 'root-mfa', choose 'Authenticator app', and scan the QR code."
step "Enter two consecutive codes to confirm."
step "Set a default region when the console prompts you: Europe (Stockholm) eu-north-1."
note "eu-north-1 because the two Claude 4.5 models are not offered in-region elsewhere,"
note "and because it is Northmill's own region."
pause "Press Enter once root MFA is active."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Create the IAM user and its policy"
say "This user is what the repository uses. It gets only what the project needs, and IAM"
say "refuses to touch any Bedrock region except Stockholm."
open_url "https://console.aws.amazon.com/iam/home#/policies"
step "Click 'Create policy' → open the JSON tab → paste the contents of:"
note "    $REPO_ROOT/aws/iam-policy.json"
step "Click Next, name it 'bedrock-agent-eval', give it the description"
note "    'Invoke and govern Bedrock in eu-north-1 for the bedrock-agent-eval project'"
step "Click 'Create policy'."
pause "Press Enter once the policy is created."
open_url "https://console.aws.amazon.com/iam/home#/users"
step "Click 'Create user'. Name it 'bedrock-agent-eval'."
step "Tick 'Provide user access to the AWS Management Console' ONLY if you want console"
note "access for it; not required. Otherwise leave it unticked and click Next."
step "Choose 'Attach policies directly', search for 'bedrock-agent-eval', tick it."
step "Create the user."
step "Open the new user → 'Security credentials' tab → 'Create access key'."
step "Choose 'Command Line Interface (CLI)', tick the acknowledgement, create it."
step "Copy BOTH values now — the secret is shown once and never again."
ask AWS_ACCESS_KEY_ID "Paste the Access key ID (starts AKIA):"
ask_secret AWS_SECRET_ACCESS_KEY "Paste the Secret access key (hidden):"
write_aws_credentials
note "Stored in ~/.aws/credentials, never in the repository."
pause "Press Enter to continue."

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Record the account id"
say "Only used to label scripts and reports. It is not a secret, but it does not belong"
say "in anything public either — the repository's .env is gitignored."
open_url "https://console.aws.amazon.com/billing/home#/account"
step "Copy the 12-digit 'Account ID' shown at the top."
ask AWS_ACCOUNT_ID "Paste the 12-digit account id:"
write_env AWS_ACCOUNT_ID "$AWS_ACCOUNT_ID"
pause "Press Enter to continue."

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Create the budget alarm"
say "A monthly budget of 10 USD with alerts at 5, 10 and forecast-10. This is the thing"
say "that turns a runaway loop from an invoice into an email."
ask BUDGET_ALERT_EMAIL "Email address for alerts:"
write_env BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"
note "Running scripts/bootstrap_aws.py ..."
pause "Press Enter to run it."
if (cd "$REPO_ROOT" && $PY scripts/bootstrap_aws.py --email "$BUDGET_ALERT_EMAIL"); then
  printf '  %s✓ created%s budget alarm and SNS topic\n' "$GREEN" "$RESET"
else
  warn "bootstrap_aws.py failed; read the message above and fix it before continuing"
  SKIPPED+=("budget alarm — re-run: make bootstrap-aws EMAIL=$BUDGET_ALERT_EMAIL")
fi
step "Check your inbox for 'AWS Notification - Subscription Confirmation' and click the link."
warn "The alarm does nothing until that link is clicked."
pause "Press Enter once you have clicked the confirmation link."

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Request Bedrock model access"
say "Bedrock is off by default. Request access to both Claude models in Stockholm."
open_url "https://console.aws.amazon.com/bedrock/home?region=eu-north-1#/modelaccess"
step "Click 'Modify model access' (or 'Enable specific models')."
step "Tick Anthropic Claude Haiku 4.5 and Anthropic Claude Sonnet 4.5."
step "Submit. If a use-case form appears, fill it in honestly:"
note "    'Building an evaluated agent prototype for a job application; public repository'"
step "Wait until both show 'Access granted'. It is usually minutes, sometimes hours."
warn "Do not continue to stage 8 until both say Access granted, or the live call will fail."
pause "Press Enter once access is granted (or once you have submitted the request)."

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Read the prices off the AWS page"
say "The cost module refuses to print money until these four numbers are real, and the"
say "pricing page renders with JavaScript so no script can fetch them. You read, I store."
open_url "https://aws.amazon.com/bedrock/pricing/"
step "Make sure the region selector says EU (Stockholm) / eu-north-1."
step "Find the Claude Haiku 4.5 row and read the Input and Output price per 1M tokens."
step "Find the Claude Sonnet 4.5 row and do the same."
note "Enter the numbers exactly as shown. If a price is per 1K tokens, multiply by 1000."
ask_number PRICE_HAIKU_INPUT "Haiku 4.5 input price per 1M tokens (USD):"
ask_number PRICE_HAIKU_OUTPUT "Haiku 4.5 output price per 1M tokens (USD):"
ask_number PRICE_SONNET_INPUT "Sonnet 4.5 input price per 1M tokens (USD):"
ask_number PRICE_SONNET_OUTPUT "Sonnet 4.5 output price per 1M tokens (USD):"
PRICES_AS_OF="$(date +%F)"
write_env PRICES_AS_OF "$PRICES_AS_OF"
write_env PRICE_HAIKU_INPUT "$PRICE_HAIKU_INPUT"
write_env PRICE_HAIKU_OUTPUT "$PRICE_HAIKU_OUTPUT"
write_env PRICE_SONNET_INPUT "$PRICE_SONNET_INPUT"
write_env PRICE_SONNET_OUTPUT "$PRICE_SONNET_OUTPUT"
note "Dated $PRICES_AS_OF. Every cost table the repository prints will carry that date."
pause "Press Enter to continue."

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Verify everything"
say "This runs every check and makes one tiny live call to prove model access."
note "Running scripts/verify_aws_setup.py --invoke ..."
pause "Press Enter to run it."
if (cd "$REPO_ROOT" && $PY scripts/verify_aws_setup.py --invoke); then
  printf '  %s✓ Phase 0 verified%s\n' "$GREEN" "$RESET"
else
  warn "some checks failed — fix them and re-run: make verify-aws ARGS=--invoke"
  SKIPPED+=("Phase 0 verification is not fully green")
fi

finish
printf '  Next: cd %s && make evals\n\n' "$REPO_ROOT"
